  Lemma of_segH4 : forall vals R M,
    length vals = 231%nat -> vals_ev vals 0 = sp0 ->
    regs_ok (ENV BL vals) srH40 R -> know_ok RSEGS (ENV BL vals) M knH40 ->
    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0xd5e0c) M (seg_rom RSEGS)) model)
